tags.gen_ai.tool.definitions:
[
  {
    "type": "function",
    "name": "get_incoming_items",
    "description": "Listet die eingehenden Requirement-Items dieses Meetings (incomingItemId, text, sourceClaimIds), die aufgeloest werden muessen.",
    "parameters": {
      "type": "object",
      "properties": {}
    }
  },
  {
    "type": "function",
    "name": "list_core_requirements",
    "description": "Listet die bestehenden Requirement-Entitaeten des Core als Kandidaten (entityId, identityKey, status, text).",
    "parameters": {
      "type": "object",
      "properties": {
        "limit": {
          "type": "integer",
          "default": 300
        }
      }
    }
  },
  {
    "type": "function",
    "name": "list_core_architecture",
    "description": "QUER-SICHT (nur lesen): die bestehenden Architektur-Entitaeten des Core (entityId, identityKey, status, text). NUR zum Pruefen auf Widersprueche (CONTRADICT) - RESTATE/REFINE/SUPERSEDE bleiben Requirement-intern.",
    "parameters": {
      "type": "object",
      "properties": {
        "limit": {
          "type": "integer",
          "default": 300
        }
      }
    }
  },
  {
    "type": "function",
    "name": "get_core_entity",
    "description": "Liest eine Core-Entitaet vollstaendig (Text, Status, Herkunft, Historie).",
    "parameters": {
      "type": "object",
      "properties": {
        "entityId": {
          "type": "string"
        }
      },
      "required": [
        "entityId"
      ]
    }
  },
  {
    "type": "function",
    "name": "list_open_decisions",
    "description": "Listet offene Entscheidungen (DEC-*, status=open_decision) mit dem widersprochenen Ziel. Pruefen, BEVOR du CONTRADICT vorschlaegst - ist der Widerspruch schon erfasst, nutze ALREADY_DECIDED.",
    "parameters": {
      "type": "object",
      "properties": {}
    }
  },
  {
    "type": "function",
    "name": "search_core",
    "description": "Sucht in den Core-Requirements nach Stichworten (entityId/text).",
    "parameters": {
      "type": "object",
      "properties": {
        "query": {
          "type": "string"
        },
        "limit": {
          "type": "integer",
          "default": 30
        }
      },
      "required": [
        "query"
      ]
    }
  },
  {
    "type": "function",
    "name": "search_rejections",
    "description": "Sucht in frueher ABGELEHNTEN Vorschlaegen (Wiedervorlage-Wissen, REJ-*). Ohne query: alle. Ist ein eingehendes Requirement inhaltlich gleich, relatedRejectionId auf der Operation setzen \u2014 trotzdem normal vorschlagen, der Mensch entscheidet.",
    "parameters": {
      "type": "object",
      "properties": {
        "query": {
          "type": [
            "string",
            "null"
          ],
          "default": null
        },
        "limit": {
          "type": "integer",
          "default": 30
        }
      }
    }
  },
  {
    "type": "function",
    "name": "check_state_change_plan",
    "description": "Prueft die Operationen deterministisch (Coverage/Ziele/Belege). Vor dem Speichern nutzen.",
    "parameters": {
      "type": "object",
      "properties": {
        "operations": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "incomingItemId": {
                "type": "string"
              },
              "kind": {
                "type": "string"
              },
              "statement": {
                "type": "string"
              },
              "targetEntityId": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "featureKey": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "claimIds": {
                "type": "array",
                "items": {
                  "type": "string"
                }
              },
              "rationale": {
                "type": "string"
              },
              "relatedRejectionId": {
                "type": [
                  "string",
                  "null"
                ],
                "default": null
              }
            },
            "required": [
              "incomingItemId",
              "kind",
              "statement",
              "targetEntityId",
              "featureKey",
              "claimIds",
              "rationale"
            ]
          }
        }
      },
      "required": [
        "operations"
      ]
    }
  },
  {
    "type": "function",
    "name": "save_state_change_plan",
    "description": "Speichert die finalen Operationen (genau eine je eingehendem Requirement). Genau einmal am Ende aufrufen.",
    "parameters": {
      "type": "object",
      "properties": {
        "operations": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "incomingItemId": {
                "type": "string"
              },
